// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { getUser } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

async function updateUserWithUnknownIdentifier(client: any, users: any, username: any, expectedStatus = 400) {
    // Request Body
    const usersPutRequestBody: string = `{
        "name": "x",
        "username": "no-such-user-zzz-9137"
    }`;

    // Execute Request
    const response = await client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/users/{users}",
        method: "PUT",
        body: usersPutRequestBody,
        pathParams: {"users": users},
        dataOverride: {"username": username}
    });

    // Generated Assertions
    expect(response.statusCode, 'status code').toBe(expectedStatus);

    return response;
}

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Declaration of variables
    const users = "testbot-admin";
    const users_1 = "no-such-user-zzz-9137";
    const users_2 = "no-such-user-zzz-9137";
    const users_3 = "no-such-user-zzz-9137";

    const usersGetResponse = await getUser(client, users, 200);
    expect(usersGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersGetResponse, "response.username"), 'username').toBe("testbot-admin");
    expect(getResponseValue(usersGetResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(usersGetResponse, "response.name"), 'name').not.toBeNull();
    expect(getResponseValue(usersGetResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getResponseValue(usersGetResponse, "response.isPrivate"), 'isPrivate carries no value').toBeNull();
    expect(getResponseValue(usersGetResponse, "response.email"), 'email carries no value').toBeNull();
    expect(getResponseValue(usersGetResponse, "response.password"), 'password carries no value').toBeNull();

    const usersGet1Response = await getUser(client, users_1, 404);
    expect(usersGet1Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(usersGet1Response, "response"), 'response').toBe("User not found.");

    const usersPutResponse = await updateUserWithUnknownIdentifier(client, users_2, users_3, 400);
    expect(usersPutResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(usersPutResponse, "response"), 'response').toBe("Invalid request.");

    const usersGet2Response = await getUser(client, getResponseValue(usersGetResponse, "response.id"), 401);
    expect(usersGet2Response.statusCode, 'status code').toBe(401);
    expect(getResponseValue(usersGet2Response, "response"), 'response').toBe("You must be logged in.");
});
